template:
#[derive(Debug)]
struct User {
    id: u32,
}

impl PartialEq for User {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

fn main() {
    let u1 = User { id: 42 };
    let u2 = User { id: 42 };
    let is_same = ⟦slot1⟧ ⟦slot2⟧ &u2;
    assert!(is_same);
}

tests:
#[test]
fn test_ref_cmp() {
    let a = User { id: 10 };
    let b = User { id: 10 };
    assert!(&a == &b);
}
